import { Tabs, useRouter } from 'expo-router';
import React, { useEffect } from 'react';
import { View, StyleSheet, Platform } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { HapticTab } from '@/components/haptic-tab';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { useAuth } from '@/context/AuthContext';

export default function TabLayout() {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  const colors = Colors[colorScheme ?? 'light'];
  const { user } = useAuth();
  const router = useRouter();
  const insets = useSafeAreaInsets();

  const isStudent = user?.role === 'student';
  const isTeacher = user?.role === 'teacher';
  const isAdmin = user?.role === 'admin' || user?.role === 'super_admin';
  const isAdminOrTeacher = isAdmin || isTeacher;

  if (isAdmin) {
    router.replace('/admin');
    return null;
  }

  const TAB_HEIGHT = 64;
  const BOTTOM_PAD = Math.max(insets.bottom, 8);

  return (
    <Tabs
      screenOptions={{
        tabBarActiveTintColor: colors.tint,
        tabBarInactiveTintColor: isDark ? '#64748B' : '#9CA3AF',
        tabBarStyle: {
          backgroundColor: isDark ? colors.cardBackground : '#fff',
          borderTopColor: 'transparent',
          borderTopWidth: 0,
          paddingBottom: BOTTOM_PAD,
          height: TAB_HEIGHT + BOTTOM_PAD,
          // Frosted glass on iOS
          ...(Platform.OS === 'ios' && {
            position: 'absolute',
            backgroundColor: isDark ? 'rgba(30,41,59,0.92)' : 'rgba(255,255,255,0.92)',
          }),
          shadowColor: '#000',
          shadowOffset: { width: 0, height: -4 },
          shadowOpacity: isDark ? 0.25 : 0.06,
          shadowRadius: 16,
          elevation: 12,
        },
        tabBarLabelStyle: {
          fontSize: 10,
          fontWeight: '600',
          letterSpacing: 0.2,
          marginTop: 2,
        },
        tabBarItemStyle: {
          paddingTop: 8,
        },
        tabBarIconStyle: {
          marginBottom: 0,
        },
        sceneContainerStyle: {
          // leave room for frosted tab bar on iOS
          ...(Platform.OS === 'ios' && { paddingBottom: TAB_HEIGHT + BOTTOM_PAD }),
        },
        headerShown: false,
        tabBarButton: HapticTab,
      }}
      initialRouteName="index"
    >
      <Tabs.Screen
        name="index"
        options={{
          title: 'Students',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="person.2.fill" color={color} />
            </View>
          ),
          href: isAdminOrTeacher ? '/(tabs)' : null,
        }}
      />
      <Tabs.Screen
        name="explore"
        options={{
          title: 'Mark Attend.',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="checkmark.circle.fill" color={color} />
            </View>
          ),
          href: isTeacher ? '/(tabs)/explore' : null,
        }}
      />
      <Tabs.Screen
        name="student-attendance"
        options={{
          title: 'Attendance',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="chart.bar.fill" color={color} />
            </View>
          ),
          href: isStudent ? '/(tabs)/student-attendance' : null,
        }}
      />
      <Tabs.Screen
        name="admin"
        options={{
          title: 'Admin',
          tabBarIcon: ({ color }) => (
            <View style={styles.pillPlaceholder}>
              <IconSymbol size={24} name="lock.shield.fill" color={color} />
            </View>
          ),
          href: null,
        }}
      />
      <Tabs.Screen
        name="history"
        options={{
          title: 'History',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="clock.fill" color={color} />
            </View>
          ),
        }}
      />
      <Tabs.Screen
        name="interactions"
        options={{
          title: 'Requests',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="tray.and.arrow.down.fill" color={color} />
            </View>
          ),
          href: isStudent ? '/(tabs)/interactions' : null,
        }}
      />
      <Tabs.Screen
        name="timetable"
        options={{
          title: 'Timetable',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="calendar.fill" color={color} />
            </View>
          ),
          href: isStudent ? '/(tabs)/timetable' : null,
        }}
      />
      <Tabs.Screen
        name="alerts"
        options={{
          title: 'Messages',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="bubble.left.and.bubble.right.fill" color={color} />
            </View>
          ),
          href: '/(tabs)/alerts',
        }}
      />
      <Tabs.Screen
        name="profile"
        options={{
          title: 'Profile',
          tabBarIcon: ({ color, focused }) => (
            <View style={focused ? [styles.pill, { backgroundColor: colors.tint + '18' }] : styles.pillPlaceholder}>
              <IconSymbol size={24} name="person.circle.fill" color={color} />
            </View>
          ),
        }}
      />
    </Tabs>
  );
}

const styles = StyleSheet.create({
  pill: {
    width: 44,
    height: 28,
    borderRadius: 14,
    justifyContent: 'center',
    alignItems: 'center',
  },
  pillPlaceholder: {
    width: 44,
    height: 28,
    justifyContent: 'center',
    alignItems: 'center',
  },
});

import { useState, useEffect } from 'react';
import { StyleSheet, View, TouchableOpacity, ActivityIndicator, RefreshControl, FlatList, TextInput } from 'react-native';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { useAuth } from '@/context/AuthContext';
import { studentInteractionsAPI } from '@/services/api';
import CommonHeader from '@/components/CommonHeader';

export default function MessagesScreen() {
  const colorScheme = useColorScheme();
  const { user, token } = useAuth();
  const [messages, setMessages] = useState<any[]>([]);
  const [conversations, setConversations] = useState<any[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [view, setView] = useState<'conversations' | 'messages'>('conversations');
  const [selectedConversation, setSelectedConversation] = useState<any>(null);
  const [messageText, setMessageText] = useState('');
  const [sendingMessage, setSendingMessage] = useState(false);

  const userId = user?.id;

  useEffect(() => {
    if (userId && token) {
      fetchConversations();
    }
  }, [userId, token]);

  const fetchConversations = async () => {
    if (!userId || !token) return;
    setLoading(true);
    try {
      const data = await studentInteractionsAPI.getConversations(userId, token);
      setConversations(data.conversations || []);
      setUnreadCount(data.unreadCount || 0);
    } catch (error: any) {
      console.error('Error fetching conversations:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchMessages = async (conversationId: string) => {
    if (!token) return;
    try {
      const data = await studentInteractionsAPI.getConversationMessages(conversationId, token);
      setMessages(data.messages || []);
    } catch (error: any) {
      console.error('Error fetching messages:', error);
    }
  };

  const handleSelectConversation = (conversation: any) => {
    setSelectedConversation(conversation);
    setView('messages');
    fetchMessages(conversation._id);
  };

  const handleSendMessage = async () => {
    if (!messageText.trim() || !selectedConversation || !token) return;

    setSendingMessage(true);
    try {
      await studentInteractionsAPI.sendMessage(selectedConversation._id, messageText, token);
      setMessageText('');
      await fetchMessages(selectedConversation._id);
    } catch (error: any) {
      console.error('Error sending message:', error);
    } finally {
      setSendingMessage(false);
    }
  };

  const onRefresh = async () => {
    setRefreshing(true);
    await fetchConversations();
    setRefreshing(false);
  };

  if (!user) {
    return (
      <ThemedView style={styles.container}>
        <ThemedText>Loading...</ThemedText>
      </ThemedView>
    );
  }

  return (
    <ThemedView style={styles.container}>
      {view === 'conversations' ? (
        <>
          <CommonHeader title="Messages" />

          {loading ? (
            <View style={styles.loadingContainer}>
              <ActivityIndicator size="large" color={Colors[colorScheme ?? 'light'].tint} />
            </View>
          ) : conversations.length === 0 ? (
            <View style={styles.emptyState}>
              <IconSymbol name="envelope.open" size={48} color={Colors[colorScheme ?? 'light'].text} />
              <ThemedText style={styles.emptyText}>No messages yet</ThemedText>
            </View>
          ) : (
            <FlatList
              data={conversations}
              keyExtractor={(item) => item._id}
              contentContainerStyle={styles.listContent}
              refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
              renderItem={({ item: conversation }) => (
                <TouchableOpacity
                  onPress={() => handleSelectConversation(conversation)}
                  activeOpacity={0.7}>
                  <ThemedView style={[styles.conversationCard, { marginHorizontal: 16 }, conversation.unreadCount > 0 && styles.conversationUnread]}>
                    <View style={styles.conversationHeader}>
                      <View style={{ flex: 1 }}>
                        <ThemedText type="defaultSemiBold" style={styles.conversationTitle}>
                          {conversation.participantName}
                        </ThemedText>
                        <ThemedText style={styles.lastMessage} numberOfLines={1}>
                          {conversation.lastMessage}
                        </ThemedText>
                      </View>
                      {conversation.unreadCount > 0 && (
                        <View style={styles.unreadBadgeCircle}>
                          <ThemedText style={styles.badgeText}>
                            {conversation.unreadCount}
                          </ThemedText>
                        </View>
                      )}
                    </View>
                    <ThemedText style={styles.timestamp}>
                      {new Date(conversation.lastMessageTime).toLocaleString()}
                    </ThemedText>
                  </ThemedView>
                </TouchableOpacity>
              )}
            />
          )}
        </>
      ) : (
        <View style={styles.messageView}>
          {/* Message Header */}
          <View style={styles.messageHeader}>
            <TouchableOpacity onPress={() => setView('conversations')} style={styles.backButton}>
              <IconSymbol name="chevron.left" size={24} color={Colors[colorScheme ?? 'light'].tint} />
            </TouchableOpacity>
            <ThemedText type="defaultSemiBold" style={styles.messageHeaderTitle}>
              {selectedConversation?.participantName}
            </ThemedText>
            <View style={styles.spacer} />
          </View>

          {/* Messages List */}
          <FlatList
            data={messages}
            keyExtractor={(item) => item._id}
            renderItem={({ item }) => (
              <View style={[
                styles.messageBubble,
                item.senderId === userId ? styles.myMessage : styles.theirMessage
              ]}>
                <ThemedText style={styles.messageContent}>
                  {item.content}
                </ThemedText>
                <ThemedText style={styles.messageTime}>
                  {new Date(item.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </ThemedText>
              </View>
            )}
            inverted
            contentContainerStyle={styles.messagesList}
          />

          {/* Message Input */}
          <View style={styles.inputContainer}>
            <TextInput
              style={styles.messageInput}
              placeholder="Type a message..."
              placeholderTextColor="#999"
              value={messageText}
              onChangeText={setMessageText}
              multiline
              editable={!sendingMessage}
            />
            <TouchableOpacity
              onPress={handleSendMessage}
              disabled={!messageText.trim() || sendingMessage}
              style={styles.sendButton}>
              <IconSymbol
                name="paperplane.fill"
                size={18}
                color={messageText.trim() ? Colors[colorScheme ?? 'light'].tint : '#ccc'}
              />
            </TouchableOpacity>
          </View>
        </View>
      )}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  badgeHeader: {
    paddingHorizontal: 16,
    paddingTop: 16,
    paddingBottom: 14,
    borderBottomLeftRadius: 18,
    borderBottomRightRadius: 18,
  },
  badgeHeaderContent: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  badgeIconContainer: {
