            </View>
          </View>

          {user?.lastLogin && (
            <View style={styles.infoRow}>
              <IconSymbol name="clock.fill" size={18} color={Colors[colorScheme ?? 'light'].tint} />
              <View style={styles.infoContent}>
                <ThemedText style={styles.infoLabel}>Last Login</ThemedText>
                <ThemedText style={styles.infoValue}>
                  {(() => {
                    const diff = Date.now() - new Date(user.lastLogin).getTime();
                    const m = Math.floor(diff / 60000);
                    if (m < 1) return 'Just now';
                    if (m < 60) return `${m} minutes ago`;
                    const h = Math.floor(m / 60);
                    if (h < 24) return `${h} hours ago`;
                    return new Date(user.lastLogin).toLocaleDateString();
                  })()}
                </ThemedText>
              </View>
            </View>
          )}
        </View>

        {/* Security Section */}
