        </View>

        <View style={styles.infoBox}>
          <ThemedText style={styles.infoText}>
            Select data type to export. Files will be saved with timestamp.
          </ThemedText>
        </View>

        {exportOptions.map((option) => (
          <TouchableOpacity
            key={option.type}
            style={styles.optionCard}
            onPress={() => handleExport(option.type)}
            disabled={loading}>
            <View style={styles.optionHeader}>
              <View style={styles.optionIconContainer}>
                <IconSymbol size={32} name={option.icon as any} color={option.color} />
              </View>
              <View style={styles.optionText}>
                <ThemedText type="defaultSemiBold" style={styles.optionLabel}>
                  {option.label}
                </ThemedText>
                <ThemedText style={styles.optionDescription}>
                  {option.description}
                </ThemedText>
              </View>
            </View>
            <View
              style={[
                styles.optionBorder,
                {
                  borderLeftColor: option.color,
                  borderTopColor: option.color,
                },
              ]}
            />
          </TouchableOpacity>
        ))}

        <View style={styles.notesBox}>
          <ThemedText type="defaultSemiBold" style={styles.notesTitle}>
            Notes
          </ThemedText>
          <ThemedText style={styles.notesText}>
            ΓÇó All exports are in JSON format{'\n'}ΓÇó Files are timestamped{'\n'}ΓÇó Contains all
            related data{'\n'}ΓÇó Ready for analysis and backup
          </ThemedText>
        </View>

        {loading && (
          <View style={styles.loadingOverlay}>
            <ActivityIndicator size="large" color={Colors[colorScheme ?? 'light'].tint} />
            <ThemedText style={styles.loadingText}>Exporting data...</ThemedText>
          </View>
        )}
      </ScrollView>
    </ThemedView>
  );
