              </LinearGradient>
            </TouchableOpacity>

            {/* ΓöÇΓöÇ Divider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
            <View style={styles.dividerRow}>
              <View style={[styles.divLine, { backgroundColor: colors.border }]} />
              <ThemedText style={[styles.divText, { color: colors.textSecondary }]}>or</ThemedText>
              <View style={[styles.divLine, { backgroundColor: colors.border }]} />
            </View>

            {/* ΓöÇΓöÇ Register link ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
            <TouchableOpacity
              style={[styles.registerBtn, { borderColor: colors.border }]}
              onPress={() => router.push('/register')}
              activeOpacity={0.8}
            >
              <ThemedText style={[styles.registerText, { color: colors.text }]}>
                Don't have an account?{' '}
                <ThemedText style={[styles.registerLink, { color: colors.tint }]}>Register</ThemedText>
              </ThemedText>
            </TouchableOpacity>
          </Animated.View>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

